// GENERATED FILE. Source of truth: docs/data/biblia-emanus/*.json
import type { PublishedEmanusOtTextBook } from "../publishedEmanusOtText.js"

export const EMANUS_TEXT_BOOK: PublishedEmanusOtTextBook = {
  order: 38,
  code: "ZEC",
  name: "Zaharia",
  chapters: {
    1: ["În luna a opta, în anul al doilea al lui Darius, cuvântul DOMNULUI a vorbit prorocului Zaharia, fiul lui Berechia, fiul lui Ido, astfel:", "„DOMNUL S-a mâniat foarte tare pe părinții voștri.”", "Spune-le, dar: „Așa vorbește DOMNUL oștirilor: «Întoarceți-vă la Mine, zice DOMNUL oștirilor, și Mă voi întoarce și Eu la voi, zice DOMNUL oștirilor.»”", "Nu fiți ca părinții voștri, cărora le vorbeau prorocii de mai înainte, zicând: „Așa vorbește DOMNUL oștirilor: «Întoarceți-vă de la căile voastre cele rele, de la faptele voastre cele rele!»” Dar ei n-au ascultat și n-au luat aminte la Mine, zice DOMNUL.", "Unde sunt acum părinții voștri? Și puteau prorocii să trăiască veșnic?", "Totuși cuvintele Mele și poruncile pe care le dădusem slujitorilor Mei prorocii ca să le vestească n-au atins ele pe părinții voștri? Și atunci ei s-au întors și au zis: „DOMNUL oștirilor ne-a făcut cum hotărâse să ne facă, după căile și faptele noastre!”", "În a douăzeci și patra zi a lunii a unsprezecea, care este luna Șebat, în anul al doilea al lui Darius, cuvântul DOMNULUI a vorbit prorocului Zaharia, fiul lui Berechia, fiul lui Ido, astfel:", "M-am uitat noaptea, și iată că un om era călare pe un cal roșu și stătea între mirți într-un umbrar; în urma lui erau niște cai roșii, murgi și albi.", "„Am întrebat: «Ce înseamnă caii aceștia, domnul meu?» Și îngerul care vorbea cu mine mi-a zis: – Îți voi arăta ce înseamnă caii aceștia!”", "Omul care stătea între mirți a luat cuvântul și a zis: „Aceștia sunt aceia pe care i-a trimis DOMNUL să cutreiere pământul!”", "Și ei au vorbit Îngerului DOMNULUI care stătea între mirți și au zis: „Am cutreierat pământul, și iată că tot pământul este în pace și liniștit!”", "Atunci Îngerul DOMNULUI a luat cuvântul și a zis: „Doamne al oștirilor, până când nu vei avea milă de Ierusalim și de cetățile lui Iuda, pe care Te-ai mâniat în acești șaptezeci de ani?”", "DOMNUL a răspuns cu vorbe bune, cu vorbe de mângâiere îngerului care vorbea cu mine.", "Și îngerul care vorbea cu mine mi-a zis: „Strigă și zi: «Așa vorbește DOMNUL oștirilor: „Sunt plin de o mare gelozie pentru Ierusalim și pentru Sion”»”", "„și sunt plin de o mare mânie împotriva neamurilor îngâmfate; căci Mă mâniasem numai puțin, dar ele au ajutat spre nenorocire.”", "De aceea așa vorbește DOMNUL: „Mă întorc cu îndurarea către Ierusalim; Casa Mea va fi zidită iarăși în el, și funia de măsurat se va întinde asupra Ierusalimului.”", "Strigă din nou și zi: „Așa vorbește DOMNUL oștirilor: «Cetățile Mele vor avea iarăși belșug de bunătăți, DOMNUL va mângâia iarăși Sionul, va alege iarăși Ierusalimul.»”", "Am ridicat ochii și m-am uitat, și iată că erau patru coarne!", "Am întrebat îngerul care vorbea cu mine: „Ce înseamnă coarnele acestea?” Și el mi-a zis: „Acestea sunt coarnele care au risipit pe Iuda, pe Israel și Ierusalimul.”", "DOMNUL mi-a arătat patru fierari.", "Eu am întrebat: „Ce vor să facă aceștia?” Și el a zis: „Aceștia vin să sperie coarnele care au risipit pe Iuda, de n-a mai putut ridica nimeni capul; fierarii aceștia au venit să sperie și să taie coarnele neamurilor care au ridicat cornul împotriva țării lui Iuda ca să-i risipească locuitorii.”"],
    2: ["Am ridicat ochii și m-am uitat, și iată că era un om care ținea în mână o funie de măsurat.", "L-am întrebat: „Unde te duci?” Și el mi-a zis: „Mă duc să măsor Ierusalimul ca să văd ce lățime și ce lungime are.”", "Și îngerul care vorbea cu mine a înaintat, și un alt înger i-a ieșit înainte.", "El i-a zis: „Aleargă de vorbește tânărului acestuia și spune-i: «Ierusalimul va fi o cetate deschisă, din pricina mulțimii oamenilor și vitelor care vor fi în mijlocul lui;»”", "Eu însumi – zice DOMNUL – voi fi un zid de foc de jur împrejurul lui și voi fi slava lui în mijlocul lui! –", "Fugiți, fugiți din țara de la miazănoapte! – zice DOMNUL. Căci v-am împrăștiat în cele patru vânturi ale cerurilor, zice DOMNUL.", "„Scapă, Sioane, tu care locuiești la fiica Babilonului!”", "Căci așa vorbește DOMNUL oștirilor: „După slavă M-a trimis El la neamurile care v-au jefuit; căci cel ce se atinge de voi se atinge de lumina ochilor Lui.”", "Iată, Îmi ridic mâna împotriva lor – zice DOMNUL – și ele vor fi prada celor ce le erau supuși, ca să știți că DOMNUL oștirilor M-a trimis.", "Strigă de veselie și bucură-te, fiica Sionului! Căci iată, Eu vin și voi locui în mijlocul tău, zice DOMNUL.", "Multe neamuri se vor alipi de DOMNUL, în ziua aceea, și vor fi poporul Meu. Eu voi locui în mijlocul tău, și vei ști că DOMNUL oștirilor M-a trimis la tine.", "DOMNUL va lua în stăpânire pe Iuda, ca partea Lui de moștenire în pământul sfânt, și va alege iarăși Ierusalimul.", "„Orice făptură să tacă înaintea DOMNULUI, căci El S-a și sculat din locașul Lui cel sfânt!”"],
    3: ["El (îngerul) mi-a arătat pe marele preot Iosua stând în picioare înaintea Îngerului DOMNULUI și pe Satana stând la dreapta lui ca să-l pârască.", "DOMNUL a zis Satanei: „DOMNUL să te mustre, Satano! DOMNUL să te mustre, El care a ales Ierusalimul! Nu este el, Iosua, un tăciune scos din foc?”", "Dar Iosua era îmbrăcat cu haine murdare și totuși stătea în picioare înaintea Îngerului.", "Iar Îngerul, luând cuvântul, a zis celor ce erau înaintea Lui: „Dezbrăcați-l de hainele murdare de pe el!” Apoi a zis lui Iosua: „Iată că îndepărtez de la tine nelegiuirea și te îmbrac cu haine de sărbătoare!”", "Eu am zis: „Să i se pună pe cap o mitră curată!” Și i-au pus o mitră curată pe cap și l-au îmbrăcat cu haine, în timp ce Îngerul DOMNULUI stătea acolo.", "Îngerul DOMNULUI a făcut lui Iosua următoarea mărturisire:", "„Așa vorbește DOMNUL oștirilor: «Dacă vei umbla pe căile Mele și dacă vei păzi poruncile Mele, vei judeca și Casa Mea și vei priveghea asupra curților Mele, și te voi lăsa să intri împreună cu cei ce sunt aici.»”", "Ascultă, dar, Iosua, mare preot, tu și tovarășii tăi de slujbă care stau înaintea ta – căci aceștia sunt niște oameni care vor sluji ca semne. – Iată, voi aduce pe Robul Meu, Odrasla.", "Căci iată că numai spre piatra aceasta pe care am pus-o înaintea lui Iosua sunt îndreptați șapte ochi; iată, Eu însumi voi săpa ce trebuie săpat pe ea, zice DOMNUL oștirilor; și într-o singură zi voi înlătura nelegiuirea țării acesteia.", "„În ziua aceea – zice DOMNUL oștirilor – vă veți pofti unii pe alții sub viță și sub smochin.”"],
    4: ["Îngerul care vorbea cu mine s-a întors și m-a trezit ca pe un om pe care-l trezești din somnul lui.", "El m-a întrebat: „Ce vezi?” Eu am răspuns: „M-am uitat, și iată că este un sfeșnic cu totul de aur, și deasupra lui, un vas cu untdelemn, și pe el, șapte candele cu câte șapte țevi pentru fiecare dintre candelele de pe vârful sfeșnicului.”", "„Și lângă el sunt doi măslini, unul la dreapta vasului, și altul, la stânga lui.”", "Și, luând iarăși cuvântul, am zis îngerului care vorbea cu mine: „Ce înseamnă lucrurile acestea, domnul meu?”", "Îngerul care vorbea cu mine mi-a răspuns: „Nu știi ce înseamnă aceste lucruri?” Eu am zis: „Nu, domnul meu.”", "Atunci el a luat din nou cuvântul și mi-a zis: „Acesta este cuvântul DOMNULUI către Zorobabel și sună astfel: «Lucrul acesta nu se va face nici prin putere, nici prin tărie, ci prin Duhul Meu – zice DOMNUL oștirilor!»”", "Cine ești tu, munte mare, înaintea lui Zorobabel? Te vei preface într-un loc șes. El va pune piatra cea mai însemnată în vârful Templului, în mijlocul strigătelor de: „Îndurare, îndurare cu ea!”", "Cuvântul DOMNULUI mi-a vorbit astfel:", "„Mâinile lui Zorobabel au întemeiat Casa aceasta și tot mâinile lui o vor isprăvi; și veți ști că DOMNUL oștirilor M-a trimis la voi.”", "„Căci cine disprețuiește ziua începuturilor slabe? Aceștia șapte vor privi cu bucurie cumpăna în mâna lui Zorobabel. Aceștia șapte sunt ochii DOMNULUI care cutreieră tot pământul.”", "Eu am luat cuvântul și i-am zis: „Ce înseamnă acești doi măslini la dreapta sfeșnicului și la stânga lui?”", "Am luat a doua oară cuvântul și i-am zis: „Ce înseamnă cele două ramuri de măslin care sunt lângă cele două țevi de aur prin care curge uleiul auriu din el?”", "El mi-a răspuns: „Nu știi ce înseamnă?” Eu am zis: „Nu, domnul meu.”", "„Aceștia sunt cei doi unși care stau înaintea DOMNULUI întregului pământ.”"],
    5: ["Am ridicat din nou ochii și m-am uitat, și iată că era un sul de carte care zbura.", "El m-a întrebat: „Ce vezi?” Eu am răspuns: „Văd un sul de carte zburând; are o lungime de douăzeci de coți și o lățime de zece coți.”", "Și el mi-a zis: „Acesta este blestemul care este peste toată țara; căci, după cum este scris pe el, orice hoț va fi nimicit potrivit cu ce este scris pe o parte a lui; și oricine jură strâmb va fi nimicit potrivit cu ce este scris pe cealaltă parte a lui.”", "„Îl trimit – zice DOMNUL oștirilor – ca să intre în casa hoțului și a celui ce jură strâmb în Numele Meu, ca să rămână în casa aceea și s-o mistuie împreună cu lemnele și pietrele ei.”", "Îngerul care vorbea cu mine a înaintat și mi-a zis: „Ridică ochii și privește ce iese de acolo.”", "Eu am răspuns: „Ce este aceasta?” Și el a zis: „Iese efa.” Și a adăugat: „Aceasta este nelegiuirea lor în toată țara.”", "Și iată că se ridica un talant de plumb, și în mijlocul efei ședea o femeie.", "El a spus: „Aceasta este Răutatea!” A împins-o înapoi în mijlocul efei și a aruncat greutatea de plumb peste gura ei.", "Am ridicat ochii și m-am uitat, și iată că s-au arătat două femei. În aripile lor sufla vântul: ele aveau aripi ca ale cocostârcului. Au ridicat efa între pământ și cer.", "Atunci am întrebat pe îngerul care vorbea cu mine: „Unde duc ele efa?”", "El mi-a răspuns: „Se duc să-i zidească o casă în țara Șinear, ca să fie așezată acolo și să rămână pe locul ei.”"],
    6: ["Am ridicat din nou ochii și m-am uitat, și iată că patru care ieșeau dintre doi munți; și munții erau de aramă.", "La carul dintâi erau niște cai roșii, la al doilea car, cai negri,", "la al treilea car, cai albi, și la al patrulea car, cai bălțați și puternici.", "Am luat cuvântul și am zis îngerului care vorbea cu mine: „Ce înseamnă aceștia, domnul meu?”", "Îngerul mi-a răspuns: „Aceștia sunt cele patru vânturi ale cerurilor care ies din locul în care stăteau înaintea DOMNULUI întregului pământ.”", "„Caii cei negri, înhămați la unul din care, s-au îndreptat spre țara de la miazănoapte, și cei albi au mers după ei; cei bălțați s-au îndreptat spre țara de miazăzi.”", "Cei puternici au ieșit și au cerut să meargă să cutreiere pământul. El le-a zis: „Duceți-vă de cutreierați pământul!” Și au cutreierat pământul.", "El m-a chemat și mi-a zis: „Iată că cei ce se îndreaptă spre țara de miazănoapte fac să se mai potolească mânia Mea în țara de la miazănoapte.”", "Cuvântul DOMNULUI mi-a vorbit astfel:", "„Să primești daruri de la prinșii de război din Babilon: Heldai, Tobia, și Iedaia – și anume să te duci tu însuți în ziua aceea în casa lui Iosia, fiul lui Țefania, unde s-au dus ei când au venit din Babilon.”", "Să iei de la ei argint și aur și să faci din el cununi și să le pui pe capul lui Iosua, fiul lui Ioțadac, marele preot.", "Și să-i spui: „Așa vorbește DOMNUL oștirilor: «Iată că un om, al cărui nume este Odrasla, va odrăsli din locul Lui și va zidi Templul DOMNULUI.»”", "„Da, El va zidi Templul DOMNULUI, va purta podoabă împărătească, va ședea și va stăpâni pe scaunul Lui de domnie, va fi preot pe scaunul Lui de domnie, și o desăvârșită unire va domni între ei amândoi.”", "Cununi vor fi pentru Helem, Tobia și Iedaia, și pentru Hen, fiul lui Țefania, ca o aducere aminte în Templul DOMNULUI.", "„Cei ce sunt departe vor veni și vor lucra la Templul DOMNULUI; și veți ști astfel că DOMNUL oștirilor M-a trimis la voi. Lucrul acesta se va întâmpla dacă veți asculta glasul DOMNULUI Dumnezeului vostru.”"],
    7: ["În anul al patrulea al împăratului Darius, cuvântul DOMNULUI a vorbit lui Zaharia, în ziua a patra a lunii a noua, care este luna Chisleu.", "Cei din Betel trimiseseră pe Șarețer și pe Reghem-Melec cu oamenii săi să se roage DOMNULUI", "și să întrebe pe preoții din Casa DOMNULUI oștirilor și pe proroci: „Trebuie să plâng și în luna a cincea și să mă înfrânez, cum am făcut atâția ani?”", "Atunci cuvântul DOMNULUI oștirilor mi-a vorbit astfel:", "„Spune la tot poporul țării și preoților: «Când ați postit și ați plâns în luna a cincea și a șaptea, în acești șaptezeci de ani, oare pentru Mine ați postit voi?»”", "Și când mâncați și beți, nu sunteți voi cei ce mâncați și beți?", "„Nu cunoașteți cuvintele pe care le-a vestit DOMNUL prin prorocii de mai înainte, când Ierusalimul era încă locuit și liniștit împreună cu cetățile lui dimprejur și când și partea de miazăzi și câmpia erau locuite?”", "Cuvântul DOMNULUI a vorbit lui Zaharia astfel:", "„Așa a vorbit DOMNUL oștirilor: «Faceți cu adevărat dreptate și purtați-vă cu bunătate și îndurare unul față de altul.»”", "„Nu asupriți pe văduvă și pe orfan, nici pe străin și pe sărac, și niciunul să nu gândească rău în inima lui împotriva fratelui său.”", "Dar ei n-au vrut să ia aminte, ci au întors spatele și și-au astupat urechile ca să n-audă.", "Și-au făcut inima ca diamantul de tare, ca să n-asculte Legea, nici cuvintele pe care li le spunea DOMNUL oștirilor prin Duhul Său, prin prorocii de mai înainte. Din pricina aceasta, DOMNUL oștirilor S-a aprins de o mare mânie.", "Când chema El, ei n-au vrut s-asculte: „De aceea nici Eu n-am vrut s-ascult, când au chemat ei, zice DOMNUL oștirilor.”", "„Ci i-am împrăștiat printre toate neamurile pe care nu le cunoșteau; țara a fost pustiită în urma lor, așa că nimeni nu mai venea și nu mai pleca din ea; și dintr-o țară plăcută cum era, au făcut un pustiu!”"],
    8: ["Cuvântul DOMNULUI oștirilor a vorbit astfel:", "„Așa vorbește DOMNUL oștirilor: «Am o mare râvnă pentru Sion și sunt stăpânit de o râvnă plină de mânie pentru el.»”", "Așa vorbește DOMNUL: „Mă întorc iarăși în Sion și vreau să locuiesc în mijlocul Ierusalimului. Ierusalimul se va chema: «Cetatea cea credincioasă», și muntele DOMNULUI oștirilor se va chema: «Muntele cel sfânt»”", "Așa vorbește DOMNUL oștirilor: „Iarăși vor ședea pe ulițele Ierusalimului bătrâni și femei în vârstă, fiecare cu toiagul în mână, din pricina marelui lor număr de zile.”", "„Ulițele cetății vor fi pline de băieți și fete care se vor juca pe ulițe.”", "Așa vorbește DOMNUL oștirilor: „Dacă lucrul acesta va părea de mirat în ochii rămășiței poporului acestuia în zilele acelea, va fi de mirat oare și în ochii Mei? – zice DOMNUL oștirilor.”", "Așa vorbește DOMNUL oștirilor: „Iată, Eu izbăvesc pe poporul Meu din țara de la răsărit și din țara de la asfințitul soarelui.”", "„Îi voi aduce înapoi, și vor locui în mijlocul Ierusalimului; ei vor fi poporul Meu, și Eu voi fi Dumnezeul lor cu adevăr și dreptate.”", "Așa vorbește DOMNUL oștirilor: „Întăriți-vă mâinile, cei ce auziți astăzi aceste cuvinte din gura prorocilor care au vorbit în ziua când s-a pus temelia Casei DOMNULUI oștirilor, când s-a început să se zidească Templul!”", "Căci înainte de aceste zile, nu era răsplată nici pentru lucrul omului, nici pentru vite. Cei ce intrau și ieșeau n-aveau nici ei pace, din pricina vrăjmașului, și Eu dezbinam pe toți oamenii unii împotriva altora.", "Acum nu voi mai face rămășiței poporului acestuia ca în trecut, zice DOMNUL oștirilor.", "Ci sămânța păcii și vița își vor da rodul, pământul își va da roadele, și cerurile își vor trimite roua; și toate aceste lucruri le voi da în stăpânirea rămășiței poporului acestuia.", "„După cum ați fost un blestem între neamuri, casa lui Iuda și casa lui Israel, tot astfel vă voi mântui, și veți fi o binecuvântare. Nu vă temeți, ci întăriți-vă mâinile!”", "Căci așa vorbește DOMNUL oștirilor: „După cum am căutat să vă fac rău, când Mă mâniau părinții voștri, zice DOMNUL oștirilor, și nu M-am căit de lucrul acesta,”", "tot așa acum Mă întorc în aceste zile și hotărăsc să fac bine Ierusalimului și casei lui Iuda. Nu vă temeți!", "Iată ce trebuie să faceți: Fiecare să spună aproapelui său adevărul; judecați în porțile voastre după adevăr și în vederea păcii;", "„niciunul să nu gândească în inima lui rău împotriva aproapelui său și nici să nu iubiți jurământul strâmb! Căci toate lucrurile acestea Eu le urăsc, zice DOMNUL.”", "Cuvântul DOMNULUI oștirilor mi-a vorbit astfel:", "„Așa vorbește DOMNUL oștirilor: «Postul din luna a patra, postul din luna a cincea, postul din luna a șaptea și postul din luna a zecea se vor preface pentru casa lui Iuda în zile de veselie și de bucurie, în sărbători de voioșie. Dar iubiți adevărul și pacea!»”", "Așa vorbește DOMNUL oștirilor: „Vor mai veni iarăși popoare și locuitori dintr-un mare număr de cetăți.”", "Locuitorii unei cetăți vor merge la cealaltă și vor zice: „Haidem să ne rugăm DOMNULUI și să căutăm pe DOMNUL oștirilor! Voi merge și eu!”", "„Și multe popoare, și multe neamuri vor veni astfel să caute pe DOMNUL oștirilor la Ierusalim și să se roage DOMNULUI.”", "Așa vorbește DOMNUL oștirilor: „În zilele acelea, zece oameni din toate limbile neamurilor vor apuca pe un iudeu de poala hainei și-i vor zice: «Vrem să mergem cu voi; căci am auzit că Dumnezeu este cu voi!»”"],
    9: ["Iată prorocia, cuvântul DOMNULUI despre țara Hadrac; și se va opri asupra Damascului. Căci DOMNUL are ochiul îndreptat asupra oamenilor și peste toate semințiile lui Israel.", "El se oprește și peste Hamat, care se mărginește cu Damascul, peste Tir și Sidon, cu toată înțelepciunea lor!", "Tirul și-a zidit o întăritură; a îngrămădit argint ca pulberea și aur ca noroiul de pe ulițe.", "Iată că DOMNUL va pune mâna pe el, îi va năpusti puterea în mare, și el însuși va fi ars cu foc.", "Ascalonul va vedea lucrul acesta, și se va teme; Gaza, de asemenea, și o va apuca un puternic cutremur; Ecronul, de asemenea, căci nădejdea lui va fi dată de rușine; va pieri împăratul din Gaza, și Ascalonul nu va mai fi locuit.", "„Străinul se va așeza în Asdod, și voi frânge mândria filistenilor.”", "Îi voi scoate sângele din gură și urâciunile idolești dintre dinți, ca să fie și el o rămășiță pentru Dumnezeul nostru și să fie ca o căpetenie din Iuda, și Ecronul, ca iebusiții.", "Voi tăbărî în jurul Casei Mele ca s-o apăr împotriva unei oștiri, împotriva celor ce se duc și vin, și nu va mai trece asupritorul peste ei, căci acum Mă uit cu ochii Mei.", "Saltă de veselie, fiica Sionului! Strigă de bucurie, fiica Ierusalimului! Iată că Împăratul tău vine la tine; El este neprihănit și biruitor, smerit și călare pe un măgar, pe un mânz, pe mânzul unei măgărițe.", "Voi nimici carele de război din Efraim și caii din Ierusalim, și arcurile de război vor fi nimicite. El va vesti neamurilor pacea și va stăpâni de la o mare la cealaltă și de la Râu până la marginile pământului.", "Însă cât pentru tine, Sioane, din pricina legământului tău pecetluit cu sânge, voi scoate pe prinșii tăi de război din groapa în care nu este apă.", "Întoarceți-vă la cetățuie, prinși de război plini de nădejde! O spun și astăzi că îți voi întoarce îndoit!", "„Căci Îmi încordez pe Iuda ca arc și iau pe Efraim ca săgeată, și voi scula pe copiii tăi, Sioane, împotriva copiilor tăi, Grecio! Te voi face ca sabia unui viteaz!”", "Dar DOMNUL Se va arăta deasupra lor, și săgeata Lui va porni ca fulgerul; DOMNUL Dumnezeu va suna din trâmbiță și va înainta în vijelia de la miazăzi.", "DOMNUL oștirilor îi va ocroti și vor mânca, și vor zdrobi pietrele de praștie, vor bea, vor face gălăgie ca amețiți de vin, vor fi plini ca un pahar de jertfă, ca și colțurile altarului.", "DOMNUL Dumnezeul lor îi va scăpa în ziua aceea ca pe turma poporului Său; căci ei sunt pietrele cununii împărătești care vor străluci în țara Sa!", "O! cât sunt de înfloritori! Cât sunt de frumoși! Grâul va înveseli pe tineri, și mustul, pe fete."],
    10: ["Cereți de la DOMNUL ploaie, ploaie de primăvară! DOMNUL scoate fulgerele și vă trimite o ploaie îmbelșugată pentru toată verdeața de pe câmp.", "Căci terafimii vorbesc nimicuri, ghicitorii prorocesc minciuni, visele mint și mângâie cu deșertăciuni. De aceea, ei rătăcesc ca o turmă, sunt nenorociți, pentru că n-au păstor.", "„Mânia Mea s-a aprins împotriva păstorilor și voi pedepsi pe țapi. Căci DOMNUL oștirilor Își cercetează turma, casa lui Iuda, și o va face ca pe calul Său de slavă în luptă.”", "Din el va ieși Piatra din capul unghiului, din el va ieși țărușul, din el va ieși arcul de război; din el vor ieși toate căpeteniile laolaltă.", "Ei vor fi ca niște viteji care calcă în picioare noroiul de pe ulițe; în luptă, se vor lupta, pentru că DOMNUL va fi cu ei; iar călăreții vor fi acoperiți de rușine.", "Voi întări casa lui Iuda și voi izbăvi casa lui Iosif; îi voi aduce înapoi, căci Mi-este milă de ei, și vor fi ca și când niciodată nu i-aș fi lepădat; căci Eu sunt DOMNUL Dumnezeul lor, și-i voi asculta.", "Efraim va fi ca un viteaz; inima lor se va bucura ca de vin; fiii lor vor vedea lucrul acesta și se vor înveseli, inima lor se va bucura în DOMNUL.", "Le voi fluiera și-i voi aduna, căci i-am răscumpărat, și se vor înmulți cum se înmulțeau odinioară.", "Îi voi risipi printre popoare, și își vor aduce aminte de Mine în țări depărtate; vor trăi împreună cu copiii lor și se vor întoarce.", "Îi voi aduce înapoi din țara Egiptului și-i voi aduna din Asiria; îi voi aduce în țara Galaadului și în Liban, și nu le va ajunge locul.", "Israel va trece prin strâmtorile mării, va lovi valurile mării, și toate adâncimile râului Nil se vor usca; mândria Asiriei va fi frântă, și toiagul de cârmuire al Egiptului va pieri.", "„Îi voi întări în DOMNUL, și vor umbla în Numele Lui, zice DOMNUL!”"],
    11: ["Deschide-ți porțile, Libanule, ca să-ți mănânce focul cedrii!", "Vaită-te, chiparosule, căci cedrul a căzut, și cei falnici sunt nimiciți! Văitați-vă, stejari din Basan, căci pădurea cea nepătrunsă a fost dată jos!", "Păstorii scot strigăte de jale, pentru că li s-a nimicit fala; puii de lei mugesc, căci desișul Iordanului este nimicit.", "Așa vorbește DOMNUL Dumnezeul meu: „Paște oile de tăiat!”", "Căci cei ce le cumpără le taie și nu se simt vinovați. Și cel ce le vinde zice: „Binecuvântat să fie DOMNUL, căci mă îmbogățesc!” Iar păstorii lor nu au milă de ele.", "„Căci nu mai am milă de locuitorii țării – zice DOMNUL – ci, iată, dau pe oameni, pe unii în mâinile altora și în mâinile împăratului lor; ei vor pustii țara, și n-o voi izbăvi din mâinile lor.”", "Atunci m-am apucat să pasc oile de tăiat, în adevăr cele mai ticăloase din turmă. Am luat două toiege: pe unul l-am numit „Îndurare”, iar pe celălalt l-am numit „Legământ”; și am păscut turma.", "Am nimicit cu desăvârșire pe cei trei păstori într-o lună: sufletul meu nu-i mai răbda și se scârbise și sufletul lor de mine.", "Și am zis: „Nu vă mai pot paște! Cea care are să moară să moară, cea care are să piară să piară, și cele ce mai rămân să se mănânce unele pe altele!”", "Mi-am luat toiagul numit „Bunăvoință” și l-am rupt, ca să desființez legământul pe care îl încheiasem cu toate popoarele.", "Și când s-a rupt, în ziua aceea, nenorocitele acelea de oi care au luat seama la mine au cunoscut astfel că acesta era cuvântul DOMNULUI.", "Eu le-am zis: „Dacă găsiți cu cale, dați-mi plata; dacă nu, nu mi-o dați!” Atunci mi-au cântărit ca plată treizeci de arginți.", "Dar DOMNUL mi-a zis: „Aruncă olarului prețul acesta scump cu care m-au prețuit!” Am luat cei treizeci de arginți și i-am aruncat olarului, în Casa DOMNULUI.", "Apoi mi-am rupt al doilea toiag, „Legături”, ca să rup frăția dintre Iuda și Israel.", "DOMNUL mi-a zis: „Ia și uneltele unui păstor nebun!”", "Căci iată că voi ridica în țară un păstor care nu va cerceta pe cele tăiate, nu va căuta pe cele risipite, nu va vindeca pe cea rănită și nu va hrăni pe cea sănătoasă; ci va mânca din carnea celor grase și le va rupe copitele!", "„Vai de păstorul de nimic care își părăsește oile! Să cadă sabia pe brațul lui și pe ochiul lui cel drept! Să i se usuce brațul de tot și să i se stingă ochiul drept!”"],
    12: ["Prorocia, cuvântul DOMNULUI despre Israel. Așa vorbește DOMNUL care a întins cerurile și a întemeiat pământul, și a întocmit duhul omului din el:", "„Iată, voi preface Ierusalimul într-un potir de amețire pentru toate popoarele dimprejur și chiar pentru Iuda, la împresurarea Ierusalimului.”", "În ziua aceea, voi face din Ierusalim o piatră grea pentru toate popoarele. Toți cei ce o vor ridica, vor fi vătămați, și toate neamurile pământului se vor strânge împotriva lui.", "În ziua aceea, zice DOMNUL, voi lovi cu amețeală pe toți caii și cu turbare pe cei ce vor călări pe ei; dar voi avea ochii deschiși asupra casei lui Iuda și voi orbi toți caii popoarelor.", "Căpeteniile lui Iuda vor zice în inima lor: „Locuitorii Ierusalimului sunt tăria mea, prin DOMNUL oștirilor, Dumnezeul lor.”", "În ziua aceea, voi face pe căpeteniile lui Iuda ca o vatră de foc sub lemn, ca o făclie aprinsă sub snopi; vor mistui în dreapta și în stânga pe toate popoarele de jur împrejur, iar Ierusalimul va fi locuit iarăși la locul lui cel vechi.", "DOMNUL va mântui mai întâi corturile lui Iuda, pentru ca slava casei lui David și fala locuitorilor Ierusalimului să nu se înalțe peste Iuda.", "În ziua aceea, DOMNUL va ocroti pe locuitorii Ierusalimului, așa că cel mai slab dintre ei va fi în ziua aceea ca David; și casa lui David va fi ca Dumnezeu, ca Îngerul DOMNULUI înaintea lor.", "În ziua aceea, voi căuta să nimicesc toate neamurile care vor veni împotriva Ierusalimului.", "Atunci voi turna peste casa lui David și peste locuitorii Ierusalimului un duh de îndurare și de rugăciune, și își vor întoarce privirile spre Mine, pe care L-au străpuns. Îl vor plânge cum plânge cineva pe singurul lui fiu, și-L vor plânge amarnic cum plânge cineva pe un întâi născut.", "În ziua aceea, va fi jale mare în Ierusalim, ca jalea din Hadadrimon, în valea Meghidonului.", "Țara se va jeli, fiecare familie deosebit: familia casei lui David deosebit, și femeile ei, deosebit; familia casei lui Natan, deosebit, și femeile ei, deosebit;", "familia casei lui Levi, deosebit, și femeile ei, deosebit; familia lui Șimei, deosebit, și femeile ei, deosebit;", "toate celelalte familii, fiecare familie, deosebit, și femeile ei, deosebit."],
    13: ["În ziua aceea, se va deschide casei lui David și locuitorilor Ierusalimului un izvor pentru păcat și necurăție.", "În ziua aceea – zice DOMNUL oștirilor – voi stârpi din țară numele idolilor, ca nimeni să nu-și mai aducă aminte de ei; voi scoate, de asemenea, din țară pe prorocii mincinoși și duhul necurat.", "Și dacă va mai proroci cineva, atunci tatăl său și mama sa, înșiși părinții lui, îi vor zice: „Tu nu vei trăi, căci ai spus minciuni în Numele DOMNULUI.” Iar tatăl său și mama sa, cei care l-au născut, îl vor străpunge când va proroci.", "În ziua aceea, prorocii se vor rușina fiecare de vedeniile lor, când vor proroci, și nu se vor mai îmbrăca într-o manta de păr ca să mintă pe oameni.", "Ci va zice: „Eu nu sunt proroc, ci sunt plugar, căci un om m-a cumpărat din tinerețea mea!”", "Și dacă-l va întreba cineva: „De unde vin aceste răni pe care le ai la mâini?”, el va răspunde: „În casa celor ce mă iubeau le-am primit.”", "Scoală-te, sabie, asupra păstorului Meu și asupra omului care Îmi este tovarăș! – zice DOMNUL oștirilor. Lovește pe păstor, și se vor risipi oile! Și Îmi voi întoarce mâna spre cei mici.", "În toată țara, zice DOMNUL, două treimi vor fi nimicite, vor pieri, iar cealaltă treime va rămâne.", "Dar treimea aceasta din urmă o voi pune în foc și o voi curăța cum se curăță argintul, o voi lămuri cum se lămurește aurul. Ei vor chema Numele Meu, și îi voi asculta; Eu voi zice: „Acesta este poporul Meu!” Și ei vor zice: „DOMNUL este Dumnezeul meu!”"],
    14: ["Iată, vine ziua DOMNULUI, când prăzile tale vor fi împărțite în mijlocul tău.", "Atunci voi strânge toate neamurile la război împotriva Ierusalimului. Cetatea va fi luată, casele vor fi jefuite, și femeile, batjocorite; jumătate din cetate va merge în robie, dar rămășița poporului nu va fi nimicită cu desăvârșire din cetate.", "Ci DOMNUL Se va arăta și va lupta împotriva acestor neamuri, cum S-a luptat în ziua bătăliei.", "Picioarele Lui vor sta în ziua aceea pe Muntele Măslinilor, care este în fața Ierusalimului, spre răsărit; Muntele Măslinilor se va despica la mijloc, spre răsărit și spre apus, și se va face o vale foarte mare: jumătate din munte se va trage înapoi spre miazănoapte, iar jumătate, spre miazăzi.", "Veți fugi atunci în valea munților Mei, căci valea dintre munți se va întinde până la Ațel; și veți fugi cum ați fugit de cutremurul de pământ de pe vremea lui Ozia, împăratul lui Iuda. Și atunci va veni DOMNUL Dumnezeul meu, și toți sfinții, împreună cu Tine!", "În ziua aceea, nu va mai fi lumină, nici frig, nici îngheț.", "Va fi o zi deosebită, cunoscută de DOMNUL, nu va fi nici zi, nici noapte, dar spre seară se va arăta lumina.", "În ziua aceea, vor izvorî ape vii din Ierusalim și vor curge jumătate spre marea de răsărit, jumătate, spre marea de apus; așa va fi și vara și iarna.", "Și DOMNUL va fi Împărat peste tot pământul. În ziua aceea, DOMNUL va fi singurul Domn, și Numele Lui va fi singurul Nume.", "Toată țara va ajunge ca șesul Iordanului, de la Gheba până la Rimon, la miazăzi de Ierusalim; iar Ierusalimul va fi înălțat și va rămâne liniștit la locul lui, de la poarta lui Beniamin până la locul porții dintâi, până la poarta unghiurilor, și de la turnul lui Hananeel până la teascurile împăratului.", "Ei vor locui în el și nu va mai fi niciun blestem în el; Ierusalimul va fi liniștit.", "Dar iată urgia cu care va lovi DOMNUL pe toate popoarele care vor lupta împotriva Ierusalimului: Le va putrezi carnea stând încă în picioare, le vor putrezi ochii în găurile lor și le va putrezi limba în gură.", "În ziua aceea, DOMNUL va trimite o mare învălmășeală în ei; unul va apuca mâna altuia și vor ridica mâna unii asupra altora.", "Iuda va lupta și el în Ierusalim, și vor strânge bogățiile tuturor neamurilor dimprejur, aurul, argintul și haine foarte multe.", "Aceeași urgie va lovi și caii, catârii, cămilele, măgarii și toate vitele care vor fi în taberele acelea.", "Toți cei ce vor mai rămâne din toate neamurile venite împotriva Ierusalimului se vor sui în fiecare an să se închine înaintea Împăratului, DOMNUL oștirilor, și să prăznuiască sărbătoarea Corturilor.", "Dacă unele din familiile pământului nu vor voi să se suie la Ierusalim ca să se închine înaintea Împăratului, DOMNUL oștirilor, nu va cădea ploaie peste ele.", "Dacă familia Egiptului nu se va sui, dacă nu va veni, nu va cădea ploaie nici peste ea; va fi lovită cu aceeași urgie cu care va lovi DOMNUL neamurile care nu se vor sui să prăznuiască sărbătoarea Corturilor.", "Aceasta va fi pedeapsa Egiptului și pedeapsa tuturor neamurilor care nu se vor sui să prăznuiască sărbătoarea Corturilor.", "În ziua aceea, va sta scris până și pe zurgălăii cailor: „Sfințenie DOMNULUI!” Și oalele din Casa DOMNULUI vor fi ca potirele înaintea altarului.", "Orice oală din Ierusalim și din Iuda va fi închinată DOMNULUI oștirilor; toți cei ce vor aduce jertfe vor veni și se vor sluji de ele ca să-și fiarbă carnea; și nu vor mai fi canaaniți în Casa DOMNULUI oștirilor, în ziua aceea."],
  },
}
